[
  {
    "schema_version": "2",
    "strategy": "general repair - propagate colors along rows and columns within grid cells",
    "program": "for each cell in grid: if cell is colored and not background and not gridline: find all same-colored cells; for each same-colored cell, fill the rectangle between them with that color if the rectangle is within the same row or column segment bounded by gridlines"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - extend colored blocks to fill gaps along rows and columns between same-colored blocks",
    "program": "for each color present: for each pair of same-colored blocks in same row: fill all cells between them with that color; for each pair of same-colored blocks in same column: fill all cells between them with that color; only fill within the grid cell boundaries (i.e., not crossing gridlines)"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - connect same-colored objects along rows and columns",
    "program": "identify all non-background, non-gridline colored cells; group by color; for each color group, for each pair of cells in the same row, fill the horizontal segment between them with that color; for each pair in the same column, fill the vertical segment between them with that color; do not fill over gridlines"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - fill gaps between same-colored cells in same row or column within the same cell block",
    "program": "for each color, for each row, find all cells of that color in that row; if there are at least two, fill all cells between the leftmost and rightmost with that color; similarly for columns; only fill within the same grid cell (i.e., between gridlines)"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - propagate color to complete rectangles between matching colored cells",
    "program": "for each color, for each pair of cells of that color that share the same row and are in the same grid cell, fill the entire row segment between them; for each pair sharing the same column and same grid cell, fill the column segment; repeat until no changes"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - fill horizontal and vertical lines between same-colored blocks",
    "program": "for each color, for each row, if there are multiple occurrences of that color in that row, fill all cells from the first to the last occurrence with that color; for each column, do the same; only fill cells that are not gridlines and not background? (actually fill only the interior of cells, not gridlines)"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - connect same-colored dots in each row and column",
    "program": "for each color, for each row, find all columns where that color appears; if more than one, fill all columns between min and max with that color; for each column, find all rows where that color appears; if more than one, fill all rows between min and max with that color; do not overwrite gridlines"
  },
  {
    "schema_version": "2",
    "strategy": "general repair - fill between same-colored cells in the same row or column within the same cell block",
    "program": "for each color, for each row, for each contiguous block of columns (i.e., between gridlines), if that color appears in that block at least twice, fill all cells in that block's row between the first and last occurrence with that color; similarly for columns"
  }
]
